<?php
declare(strict_types=1);
session_start();
require dirname(__DIR__).'/config/config.php';
require_sign_in();
$role=$_SESSION['role']??'';if(!in_array($role,['system_admin','sub_admin'],true)){http_response_code(403);exit('Your role cannot view network requests.');}
$q=db()->query('SELECT r.*,s.name school_name,u.name requested_by_name,reviewer.name reviewer_name FROM school_edit_requests r JOIN schools s ON s.id=r.school_id JOIN users u ON u.id=r.requested_by LEFT JOIN users reviewer ON reviewer.id=r.reviewed_by ORDER BY r.created_at DESC');$requests=$q->fetchAll();$pending=array_values(array_filter($requests,static fn($r)=>$r['status']==='pending'));$accepted=array_values(array_filter($requests,static fn($r)=>in_array($r['status'],['approved','reverted'],true)));$denied=array_values(array_filter($requests,static fn($r)=>$r['status']==='denied'));
$renderRequests=static function(array $items,bool $showReview=false):void{if(!$items):?><div class="empty-state"><h3>No requests in this section</h3><p>Requests will appear here when they match this status.</p></div><?php return;endif;?><div class="request-card-list"><?php foreach($items as $request):?><article class="request-card"><div class="request-card-top"><div><div class="eyebrow"><?=e($request['school_name'])?></div><h3><?=e($request['proposed_name'])?></h3><p class="muted"><?=e($request['proposed_location']?:'No location')?> · <?=e($request['proposed_phone']?:'No phone')?></p></div><span class="request-status <?=e($request['status'])?>"><?=e($request['status']==='approved'?'Accepted':ucfirst($request['status']))?></span></div><div class="request-card-meta"><span>Requested by <strong><?=e($request['requested_by_name'])?></strong></span><span><?=e(date('j M Y · H:i',strtotime($request['created_at'])))?></span><?php if($request['reviewer_name']):?><span>Reviewed by <strong><?=e($request['reviewer_name'])?></strong></span><?php endif;?></div><details><summary>Original details</summary><p><?=e($request['original_name'])?> · <?=e($request['original_location']?:'No location')?> · <?=e($request['original_phone']?:'No phone')?></p></details><?php if($showReview):?><div class="request-card-actions"><a class="button primary" href="school_edit_review.php?id=<?=$request['school_id']?>#requests">Review request</a></div><?php elseif($request['status']==='approved'):?><div class="request-card-actions"><a class="button" href="school_edit_review.php?id=<?=$request['school_id']?>">View school and revert</a></div><?php endif;?></article><?php endforeach;?></div><?php };
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Requests · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script></head><body><div class="app-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="index.php"><span class="brand-mark">S</span><span>shule<span class="brand-lite">lite</span></span></a><div class="workspace-label">WORKSPACE</div><nav class="side-nav" aria-label="Main navigation"><a class="nav-item" href="index.php">⌂ &nbsp;Overview</a><a class="nav-item" href="schools.php">▦ &nbsp;Schools</a><a class="nav-item" href="team.php">♧ &nbsp;Team</a><a class="nav-item active" href="requests.php">✉ &nbsp;Requests<?php if($pending):?><span class="side-nav-count"><?=count($pending)?></span><?php endif;?></a><a class="nav-item" href="audit.php">◷ &nbsp;Audit log</a><a class="nav-item" href="academics.php">▤ &nbsp;Academics</a><a class="nav-item" href="notes.php">▧ &nbsp;Learning notes</a></nav><div class="sidebar-bottom"><a class="nav-item" href="logout.php">↪ &nbsp;Sign out</a></div></aside><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Workspace <span>/</span> Requests</div><a class="notification-bell" href="#requested" aria-label="<?=$pending?count($pending):0?> pending requests" title="<?=$pending?count($pending):0?> pending requests"><span aria-hidden="true">🔔</span><?php if($pending):?><span class="notification-badge"><?=count($pending)?></span><?php endif;?></a><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e($_SESSION['name']??'')?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">NETWORK REQUESTS</div><h1>School edit requests</h1><p class="muted">Review proposed school detail changes and track completed decisions.</p></div></section><nav class="request-tabs" aria-label="Request status"><a href="#requested">Requested <span><?=count($pending)?></span></a><a href="#accepted">Accepted <span><?=count($accepted)?></span></a><a href="#denied">Denied <span><?=count($denied)?></span></a></nav><section class="content-section request-status-section" id="requested"><div class="section-heading"><div><div class="eyebrow">NEEDS REVIEW</div><h2>Requested</h2></div><span class="count-pill"><?=count($pending)?> pending</span></div><?php $renderRequests($pending,true);?></section><section class="content-section request-status-section" id="accepted"><div class="section-heading"><div><div class="eyebrow">DECISION MADE</div><h2>Accepted</h2></div><span class="count-pill"><?=count($accepted)?> accepted</span></div><?php $renderRequests($accepted);?></section><section class="content-section request-status-section" id="denied"><div class="section-heading"><div><div class="eyebrow">DECISION MADE</div><h2>Denied</h2></div><span class="count-pill"><?=count($denied)?> denied</span></div><?php $renderRequests($denied);?></section></div></main></div></body></html>
